      for (ii = 0; ii < _PB_N; ii += TS) {
        int i_end = ii + TS < _PB_N ? ii + TS : _PB_N;
        for (i = ii; i < i_end; i++) {
          DATA_TYPE ri = r[i];
          #pragma omp simd
          for (j = jj; j < j_end; j++)
            s[j] += A[i][j] * ri;
        }
      }
    }
  }
#pragma endscop
}
